      "لكل مواسع حد أقصى لفرق الجهد الآمن يُكتب عليه، وتجاوز هذا الجهد يؤدي إلى تلف المواسع مباشرة.",
      "تتوقف عملية شحن المواسع تماماً عندما يتساوى فرق الجهد بين صفيحتيه مع فرق جهد البطارية المتصلة به."
