      "تُحسب قيمة التيار الكهربائي في الدارة البسيطة باستخدام العلاقة الرياضية: I = Σℰ / Σ(R + r).",
      "يوضح التمثيل البياني لتغيرات الجهد ارتفاعه عبر القوة الدافعة للبطارية وانخفاضه عبر المقاومات الداخلية والخارجية.",
      "تتفق معادلة قدرة البطارية (Iℰ = I²r + I²R) تماماً مع مبدأ حفظ الطاقة في الدارة الكهربائية.",
      "تُقاس القدرة الكهربائية بوحدة الواط (Watt)، وتُحسب القدرة المستهلكة في المقاومة الخارجية بالعلاقة: P = I²R = IV = V²/R."
